import { useEffect, useState } from "react";

function FacultyList() {
  const [selectedFaculty, setSelectedFaculty] = useState(null);
  const [rating, setRating] = useState("");
  const [comment, setComment] = useState("");
  const [faculties, setFaculties] = useState([]);
  const [facultyFeedback, setFacultyFeedback] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchFaculties();
  }, []);

  const fetchFaculties = async () => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch("http://localhost:5001/faculties", {
        method: "GET",
        headers: {
          Authorization: "Bearer " + token,
        },
      });

      const data = await response.json();
      setFaculties(data);
    } catch (error) {
      console.error("Error fetching faculties:", error);
    }
  };

  const handleSubmit = async () => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch("http://localhost:5001/feedback", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + token,
        },
        body: JSON.stringify({
          faculty_id: selectedFaculty.id,
          rating: rating,
          comment: comment,
        }),
      });

      const data = await response.json();

      if (response.ok) {
        alert("Feedback Submitted ✅");
        setRating("");
        setComment("");
        fetchFeedback(selectedFaculty.id); // refresh feedback after submit
      } else {
        alert(data.message);
      }
    } catch (error) {
      console.error("Error submitting feedback:", error);
    }
  };

  const fetchFeedback = async (facultyId) => {
    try {
      setLoading(true);
      setFacultyFeedback(null);

      const token = localStorage.getItem("token");

      const response = await fetch(
        `http://localhost:5001/faculties/${facultyId}/feedback`,
        {
          method: "GET",
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      );

      const data = await response.json();
      console.log("Feedback API Response:", data);

      if (response.ok) {
        setFacultyFeedback(data);
      } else {
        alert(data.message);
      }
    } catch (error) {
      console.error("Fetch feedback error:", error);
      alert("Unable to fetch feedback");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Faculty List</h2>

      {faculties.map((faculty) => (
        <div key={faculty.id} style={{ border: "1px solid #ccc", padding: "15px", marginBottom: "15px", borderRadius: "8px" }}>
          <p><b>{faculty.name}</b></p>
          <p><b>Designation:</b> {faculty.designation}</p>
          <p><b>Department:</b> {faculty.department}</p>
          <p><b>Email:</b> {faculty.email}</p>
          <p><b>Mobile:</b> {faculty.mobile_no}</p>

          <button
            onClick={() => {
              setSelectedFaculty(faculty);
              setFacultyFeedback(null);
            }}
          >
            Give Feedback
          </button>

          <button
            onClick={() => {
              setSelectedFaculty(faculty);
              fetchFeedback(faculty.id);
            }}
            style={{ marginLeft: "10px" }}
          >
            View Feedback
          </button>

          {/* Show Feedback Form under selected faculty */}
          {selectedFaculty?.id === faculty.id && (
            <div style={{ marginTop: "15px", padding: "10px", background: "#f9f9f9", borderRadius: "8px" }}>
              <h3>Feedback for {selectedFaculty.name}</h3>

              <input
  type="number"
  placeholder="Rating (0-5)"
  value={rating}
  min="0"
  max="5"
  step="1"
  onChange={(e) => {
    let value = e.target.value;

    if (value === "") {
      setRating("");
      return;
    }

    value = Number(value);

    if (value >= 0 && value <= 5) {
      setRating(value);
    }
  }}
/>

              <br /><br />

              <input
                type="text"
                placeholder="Comment"
                value={comment}
                onChange={(e) => setComment(e.target.value)}
              />

              <br /><br />

              <button onClick={handleSubmit}>Submit Feedback</button>
            </div>
          )}

          {/* Loading */}
          {loading && selectedFaculty?.id === faculty.id && (
            <p style={{ marginTop: "10px" }}>Loading feedback...</p>
          )}

          {/* Show Feedback under same faculty */}
          {facultyFeedback && selectedFaculty?.id === faculty.id && (
            <div style={{ marginTop: "15px", padding: "10px", background: "#eef6ff", borderRadius: "8px" }}>
              <h3>Feedback for {facultyFeedback?.faculty?.name}</h3>
              <p><b>Department:</b> {facultyFeedback?.faculty?.department}</p>
              <p><b>Average Rating:</b> {facultyFeedback?.averageFeedback}</p>
              <p><b>Total Feedback:</b> {facultyFeedback?.totalFeedback}</p>

              {facultyFeedback?.feedback?.length > 0 ? (
                facultyFeedback.feedback.map((item, index) => (
                  <div key={index}>
                    <p><b>Rating:</b> {item.rating} ⭐</p>
                    <p><b>Comment:</b> {item.comment}</p>
                    <hr />
                  </div>
                ))
              ) : (
                <p>No feedback available yet.</p>
              )}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

export default FacultyList;
